import React, { useEffect, useState } from 'react'
import './App.css'
import mockQuestions from './data'

function Quiz() {

  const [questions,setQuestions]=useState([]);
  const [loading,setLoading]=useState(true);
  const [currentQuestion,setCurrentQuestion]=useState()
  const [score, setScore] = useState(0);

  useEffect(()=>{
    const fetchQuestions = async()=>{
      try {
        const res=await fetch ('https://opentdb.com/api.php?amount=10')
        const data=await res.json();
        console.log(data)
        setQuestions(data.results);
        setLoading(false);
      } catch (error) {
        console.log("Error Fetching Questions , using mock data",error)
        setQuestions(mockQuestions);
        setLoading(false);
      }
    }
    fetchQuestions();
  },[]);

  if(loading){
    return<h3>Loading Questions ...</h3>
  }
  return (
    <div className='quiz-container '>
      <p className='quiz-header'>Quiz Quest</p>
      <p className='score-display'>Score: {score}</p>
      {
        questions.map((quest, index) => (
          <div key={index}>
            <p className='question-text'>in greek </p>
            <ul className='answers-container'>
              <button className='answer-button'>True</button>
            </ul>
            <p className='feedback'>Correct Answer</p>
          </div>
        ))
      }

    </div>
  )
}

export default Quiz
